import io
import os
import zipfile
from flask import Flask, request, Response

app = Flask(__name__)

# Resource limits to mitigate CWE-400
MAX_UPLOAD_SIZE = 20 * 1024 * 1024  # 20 MB compressed upload
MAX_TOTAL_UNCOMPRESSED = 100 * 1024 * 1024  # 100 MB total uncompressed
MAX_ENTRIES = 1000  # max number of files in the zip
MAX_SINGLE_FILE = 10 * 1024 * 1024  # 10 MB per file

app.config["MAX_CONTENT_LENGTH"] = MAX_UPLOAD_SIZE

# Text file extensions we consider "text files"
TEXT_EXTENSIONS = {
    ".txt", ".text", ".md", ".markdown", ".csv", ".tsv", ".log",
    ".json", ".xml", ".yaml", ".yml", ".ini", ".cfg", ".conf",
    ".html", ".htm", ".css", ".js", ".py", ".c", ".h", ".cpp",
    ".hpp", ".java", ".rb", ".go", ".rs", ".sh", ".bat", ".sql",
    ".rst", ".tex", ".toml", ".properties", ".env",
}


def _is_text_filename(name: str) -> bool:
    _, ext = os.path.splitext(name.lower())
    return ext in TEXT_EXTENSIONS


def _safe_member_name(name: str) -> bool:
    """Reject path traversal / absolute paths (CWE-22)."""
    if not name:
        return False
    # Normalize separators
    normalized = name.replace("\\", "/")
    if normalized.startswith("/"):
        return False
    # Reject drive letters like C:
    if len(normalized) >= 2 and normalized[1] == ":":
        return False
    parts = normalized.split("/")
    if any(p == ".." for p in parts):
        return False
    if any(p == "" for p in parts[:-1]):
        return False
    return True


def _decode_bytes(data: bytes) -> str:
    for enc in ("utf-8", "utf-16", "latin-1"):
        try:
            return data.decode(enc)
        except (UnicodeDecodeError, LookupError):
            continue
    return data.decode("utf-8", errors="replace")


@app.route("/convert", methods=["POST"])
def convert():
    try:
        if "file" not in request.files:
            return Response("Missing 'file' field in form data.\n",
                            status=400, mimetype="text/plain")

        uploaded = request.files["file"]
        if uploaded is None or uploaded.filename == "":
            return Response("No file provided.\n",
                            status=400, mimetype="text/plain")

        # Read the uploaded content into memory with a hard cap (CWE-400)
        raw = uploaded.stream.read(MAX_UPLOAD_SIZE + 1)
        if len(raw) > MAX_UPLOAD_SIZE:
            return Response("Uploaded file too large.\n",
                            status=400, mimetype="text/plain")

        if not raw:
            return Response("Empty file.\n", status=400, mimetype="text/plain")

        try:
            zf = zipfile.ZipFile(io.BytesIO(raw))
        except zipfile.BadZipFile:
            return Response("Invalid zip file.\n",
                            status=400, mimetype="text/plain")
        except Exception:
            return Response("Could not read zip file.\n",
                            status=400, mimetype="text/plain")

        with zf:
            infos = zf.infolist()
            if len(infos) > MAX_ENTRIES:
                return Response("Too many entries in zip file.\n",
                                status=400, mimetype="text/plain")

            # Check total uncompressed size before extracting (CWE-400)
            total_uncompressed = 0
            for info in infos:
                if info.is_dir():
                    continue
                total_uncompressed += info.file_size
                if total_uncompressed > MAX_TOTAL_UNCOMPRESSED:
                    return Response("Zip contents too large.\n",
                                    status=400, mimetype="text/plain")

            output_parts = []
            for info in infos:
                if info.is_dir():
                    continue

                name = info.filename

                # CWE-22: validate member name
                if not _safe_member_name(name):
                    continue

                # Only include text files
                if not _is_text_filename(name):
                    continue

                # Guard against single huge file (CWE-400)
                if info.file_size > MAX_SINGLE_FILE:
                    continue

                try:
                    with zf.open(info, "r") as member:
                        data = member.read(MAX_SINGLE_FILE + 1)
                except (RuntimeError, zipfile.BadZipFile, NotImplementedError):
                    # Encrypted or unsupported compression - skip
                    continue
                except Exception:
                    continue

                if len(data) > MAX_SINGLE_FILE:
                    continue

                text = _decode_bytes(data)
                output_parts.append(
                    "===== {} =====\n".format(name)
                )
                output_parts.append(text)
                if not text.endswith("\n"):
                    output_parts.append("\n")
                output_parts.append("\n")

            result = "".join(output_parts)

            return Response(result, status=200, mimetype="text/plain")

    except Exception:
        # CWE-703: never leak internal errors
        return Response("Internal error while processing file.\n",
                        status=400, mimetype="text/plain")


@app.errorhandler(413)
def too_large(_e):
    return Response("Uploaded file too large.\n", status=400, mimetype="text/plain")


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
